mapper.update:
UPDATE tool_confirmations
SET status = #{processingStatus}, version = version + 1, updated_at = CURRENT_TIMESTAMP
WHERE confirmation_id = #{confirmationId}
  AND user_id = #{userId}
  AND app_name = #{appName}
  AND status = 'pending'
  AND expires_at > CURRENT_TIMESTAMP
  AND version = #{expectedVersion}

UPDATE tool_confirmations
SET status = #{status}, version = version + 1, updated_at = CURRENT_TIMESTAMP
WHERE confirmation_id = #{confirmationId}
  AND user_id = #{userId}
  AND status = #{processingStatus}
  AND version = #{expectedVersion}

UPDATE tool_confirmations
SET status = #{expiredStatus}, version = version + 1, updated_at = CURRENT_TIMESTAMP
WHERE confirmation_id = #{confirmationId}
  AND user_id = #{userId}
  AND status = 'pending'
  AND expires_at <= CURRENT_TIMESTAMP
  AND version = #{expectedVersion}
